from datetime import datetime

from nonebot_plugin_orm import Model
from sqlalchemy import Float, Text
from sqlalchemy.orm import Mapped, mapped_column

# 这些列必须显式声明 Float：SQLAlchemy 2.1 起 Python 的 float 默认映射到 Double
# （渲染为 DOUBLE PRECISION），而历史迁移里建的是 FLOAT，会导致
# nonebot-plugin-orm 的 autogenerate 漂移检查在启动时报
# AutogenerateDiffsDetected。显式写 Float 可让 2.0 / 2.1 行为一致。


class UserInfo(Model):
    """用户信息"""

    id: Mapped[int] = mapped_column(primary_key=True)
    user_id: Mapped[int]
    target_weight: Mapped[float | None] = mapped_column(Float)
    target_body_fat: Mapped[float | None] = mapped_column(Float)


class FitnessRecord(Model):
    """健身记录"""

    id: Mapped[int] = mapped_column(primary_key=True)
    user_id: Mapped[int]
    time: Mapped[datetime] = mapped_column(default=datetime.utcnow)
    message: Mapped[str] = mapped_column(Text)


class DietaryRecord(Model):
    """饮食记录"""

    id: Mapped[int] = mapped_column(primary_key=True)
    user_id: Mapped[int]
    time: Mapped[datetime] = mapped_column(default=datetime.utcnow)
    healthy: Mapped[bool]


class WeightRecord(Model):
    """体重记录"""

    id: Mapped[int] = mapped_column(primary_key=True)
    user_id: Mapped[int]
    time: Mapped[datetime] = mapped_column(default=datetime.utcnow)
    weight: Mapped[float] = mapped_column(Float)


class BodyFatRecord(Model):
    """体脂记录"""

    id: Mapped[int] = mapped_column(primary_key=True)
    user_id: Mapped[int]
    time: Mapped[datetime] = mapped_column(default=datetime.utcnow)
    body_fat: Mapped[float] = mapped_column(Float)
